SELECT 
FROM public.images
WHERE game_id = #{gameId}

    AND (
        strpos(lower(image_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND enabled = #{enabled}

ORDER BY image_key ASC

SELECT 
FROM public.images
WHERE game_id = #{gameId} AND image_key = #{imageKey}

SELECT image_key, enabled, CASE WHEN enabled THEN image_base64 ELSE NULL END AS image_base64, updated_at FROM public.images WHERE game_id = #{gameId}
AND updated_at > #{updatedAfter}
ORDER BY image_key ASC

SELECT COUNT(1)
FROM public.images
WHERE game_id = #{gameId} AND image_key = #{imageKey}

SELECT COUNT(1)
FROM public.images
WHERE game_id = #{gameId}
  AND lower(btrim(name)) = lower(btrim(#{name}))

    AND image_key <> #{excludeImageKey}

mapper.update:
UPDATE public.images SET name = #{name}, description = #{description}, enabled = #{enabled},
image_base64 = #{imageBase64}, mime_type = #{mimeType}, byte_size = #{byteSize}, width = #{width}, height = #{height},
updated_at = now() WHERE game_id = #{gameId} AND image_key = #{imageKey}
